solution.css:
:root {
  --nw-color-surface: #ffffff;
  --nw-color-text: #1f2933;
  --nw-color-border: #c5ccd3;
  --nw-color-action-bg: #1f5ae0;
  --nw-color-action-text: #ffffff;
  --nw-color-danger-bg: #c62828;
  --nw-color-danger-text: #ffffff;
}

/* Base = the secondary variant */
.nw-button {
  --nw-button-bg: var(--nw-color-surface);
  --nw-button-text: var(--nw-color-text);
  --nw-button-border: var(--nw-color-border);
  --nw-button-padding-y: 8px;
  --nw-button-padding-x: 16px;

  background: var(--nw-button-bg);
  color: var(--nw-button-text);
  border: 1px solid var(--nw-button-border);
  padding: var(--nw-button-padding-y) var(--nw-button-padding-x);
  border-radius: 6px;
  font: inherit;
}
.row { display: flex; gap: 8px; flex-wrap: wrap; }

.nw-button[data-variant="primary"] {
  --nw-button-bg: var(--nw-color-action-bg);
  --nw-button-text: var(--nw-color-action-text);
  --nw-button-border: transparent;
}
.nw-button[data-variant="danger"] {
  --nw-button-bg: var(--nw-color-danger-bg);
  --nw-button-text: var(--nw-color-danger-text);
  --nw-button-border: transparent;
}
.nw-button[data-size="sm"] {
  --nw-button-padding-y: 4px;
  --nw-button-padding-x: 12px;
}
